export const EmailNotifySettingsSchema = {
  type: "object",
  description:
    "Per-tenant email alert and digest settings (m62+). Returns sensible defaults (enabled=false, digest_enabled=false) when no settings row has been created yet — this endpoint never 404s. `recipients` is a single shared list used for both per-failure alerts and the digest.\n",
  required: [
    "enabled",
    "recipients",
    "alert_on_failure",
    "alert_throttle_minutes",
    "digest_enabled",
    "digest_cadence",
    "digest_day",
    "digest_hour",
    "timezone",
    "instance_mailer_configured",
  ],
  properties: {
    enabled: {
      type: "boolean",
      description:
        "Master switch for email notifications. Both alerts and the digest require this to be true in addition to their own toggle.\n",
    },
    recipients: {
      type: "array",
      maxItems: 20,
      items: {
        type: "string",
        format: "email",
      },
      description:
        "Shared recipient list for both per-failure alerts and the digest (max 20).\n",
    },
    alert_on_failure: {
      type: "boolean",
      description: "Whether per-failure email alerts are active.",
    },
    alert_throttle_minutes: {
      type: "integer",
      description:
        "Minimum minutes between two alerts for the same site (15-1440). Default 60.\n",
    },
    digest_enabled: {
      type: "boolean",
      description: "Whether the scheduled digest email is active.",
    },
    digest_cadence: {
      type: "string",
      enum: ["daily", "weekly", "monthly"],
      description:
        "How often the digest is sent. Only enforced when digest_enabled is true.\n",
    },
    digest_day: {
      type: "integer",
      description:
        "For weekly cadence: 0=Sunday...6=Saturday. For monthly cadence: 1-28. Not used for daily cadence. Only enforced when digest_enabled is true.\n",
    },
    digest_hour: {
      type: "integer",
      description:
        "Hour (0-23), in `timezone`, at which the digest fires. Default 8.\n",
    },
    timezone: {
      type: "string",
      description: "IANA timezone used to evaluate digest_hour/digest_day.",
    },
    next_digest_at: {
      type: ["string", "null"],
      format: "date-time",
      description:
        "Next scheduled digest send time, or null when the digest is disabled or not yet scheduled.\n",
    },
    instance_mailer_configured: {
      type: "boolean",
      description:
        "True when the instance-level SMTP/mailer is configured. Alerts and digests require this to be true to deliver.\n",
    },
    failure_detection: {
      type: "object",
      description:
        "Coverage of the tenant's connected sites for email delivery failure detection (GH #381). A site is covered when EITHER WPMgr is the mail transport it actively uses (routing does not depend on agent version) OR its agent is new enough (>= min_agent_version_unrouted) to capture a failure on mail WPMgr does not route. A site that is neither routed nor on a new enough agent cannot trigger a per-failure alert no matter how the settings above are configured.\n",
      required: [
        "sites_total",
        "sites_covered",
        "sites_routed",
        "min_agent_version_unrouted",
      ],
      properties: {
        sites_total: {
          type: "integer",
          description:
            "Number of the tenant's currently-connected sites (excludes pending, degraded, disconnected, revoked and archived sites).\n",
        },
        sites_covered: {
          type: "integer",
          description:
            "Of sites_total, how many can have a delivery failure detected and alerted on — because WPMgr routes their mail, because their agent_version is at or above min_agent_version_unrouted, or both.\n",
        },
        sites_routed: {
          type: "integer",
          description:
            "Of sites_total, how many have WPMgr configured as their active mail transport. These sites are covered regardless of agent version; this count explains why sites_covered can be high even on a fleet below min_agent_version_unrouted.\n",
        },
        min_agent_version_unrouted: {
          type: "string",
          description:
            "Minimum agent version needed to detect and report a delivery failure ONLY for sites that do NOT route their mail through WPMgr (sites_total - sites_routed of them). It says nothing about routed sites, which are covered independent of this value.\n",
        },
      },
    },
    tenant_id: {
      type: ["string", "null"],
      format: "uuid",
      description:
        "Present when a settings row exists; absent for default response.",
    },
    created_at: {
      type: ["string", "null"],
      format: "date-time",
    },
    updated_at: {
      type: ["string", "null"],
      format: "date-time",
    },
  },
} as const;

